{"file_path":"src/heap.js","content":"/**
 * Binary min-heap with an index from key to position.
 *
 * Entries are ordered by priority, then by insertion order for ties. The
 * index map lets keyed operations (has, priorityOf, decreaseKey,
 * setPriority, remove) run in O(log n) or O(1) instead of scanning.
 */
export class IndexedHeap {
  /** @type {Array<{key: string, priority: number, seq: number}>} */
  #items = [];

  /** @type {Map<string, number>} */
  #index = new Map();

  /** @type {number} */
  #nextSeq = 0;

  /** @returns {number} Number of entries currently held. */
  get size() {
    return this.#items.length;
  }

  /**
   * Validates a key.
   * @param {unknown} key Candidate key.
   * @returns {void}
   */
  #checkKey(key) {
    if (typeof key !== 'string') throw new TypeError('key must be a string');
  }

  /**
   * Validates a priority.
   * @param {unknown} priority Candidate priority.
   * @returns {void}
   */
  #checkPriority(priority) {
    if (typeof priority !== 'number' || !Number.isFinite(priority)) {
      throw new TypeError('priority must be a finite number');
    }
  }

  /**
   * Compares two entries by heap order.
   * @param {{priority: number, seq: number}} a First entry.
   * @param {{priority: number, seq: number}} b Second entry.
   * @returns {boolean} True when a should leave before b.
   */
  #less(a, b) {
    return a.priority < b.priority || (a.priority === b.priority && a.seq < b.seq);
  }

  /**
   * Swaps two positions in the heap array and updates the index.
   * @param {number} i First position.
   * @param {number} j Second position.
   * @returns {void}
   */
  #swap(i, j) {
    const items = this.#items;
    [items[i], items[j]] = [items[j], items[i]];
    this.#index.set(items[i].key, i);
    this.#index.set(items[j].key, j);
  }

  /**
   * Moves the entry at a position up until heap order is restored.
   * @param {number} pos Starting position.
   * @returns {void}
   */
  #siftUp(pos) {
    const items = this.#items;
    while (pos > 0) {
      const parent = (pos - 1) >> 1;
      if (this.#less(items[pos], items[parent])) {
        this.#swap(pos, parent);
        pos = parent;
      } else break;
    }
  }

  /**
   * Moves the entry at a position down until heap order is restored.
   * @param {number} pos Starting position.
   * @returns {void}
   */
  #siftDown(pos) {
    const items = this.#items;
    const n = items.length;
    for (;;) {
      const left = pos * 2 + 1;
      const right = pos * 2 + 2;
      let smallest = pos;
      if (left < n && this.#less(items[left], items[smallest])) smallest = left;
      if (right < n && this.#less(items[right], items[smallest])) smallest = right;
      if (smallest === pos) break;
      this.#swap(pos, smallest);
      pos = smallest;
    }
  }

  /**
   * Removes the entry at a given position, keeping the heap consistent.
   * @param {number} pos Position to remove.
   * @returns {{key: string, priority: number}} Removed entry.
   */
  #removeAt(pos) {
    const items = this.#items;
    const removed = items[pos];
    const last = items.length - 1;
    this.#index.delete(removed.key);
    if (pos !== last) {
      items[pos] = items[last];
      items.pop();
      this.#index.set(items[pos].key, pos);
      this.#siftDown(pos);
      this.#siftUp(pos);
    } else {
      items.pop();
    }
    return { key: removed.key, priority: removed.priority };
  }

  /**
   * Adds an entry.
   * @param {string} key Unique key.
   * @param {number} priority Ordering priority; smaller leaves first.
   * @returns {void}
   */
  push(key, priority) {
    this.#checkKey(key);
    this.#checkPriority(priority);
    if (this.#index.has(key)) throw new Error(`duplicate key: "${key}"`);
    const entry = { key, priority, seq: this.#nextSeq };
    this.#nextSeq += 1;
    const pos = this.#items.length;
    this.#items.push(entry);
    this.#index.set(key, pos);
    this.#siftUp(pos);
  }

  /**
   * Reads the next entry without removing it.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  peek() {
    if (this.#items.length === 0) return undefined;
    const { key, priority } = this.#items[0];
    return { key, priority };
  }

  /**
   * Removes and returns the next entry.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  pop() {
    if (this.#items.length === 0) return undefined;
    return this.#removeAt(0);
  }

  /**
   * Reports whether a key is held.
   * @param {string} key Key to look up.
   * @returns {boolean} True when the key is held.
   */
  has(key) {
    this.#checkKey(key);
    return this.#index.has(key);
  }

  /**
   * Reads the priority stored for a key.
   * @param {string} key Key to look up.
   * @returns {number | undefined} Stored priority, or undefined when absent.
   */
  priorityOf(key) {
    this.#checkKey(key);
    const pos = this.#index.get(key);
    if (pos === undefined) return undefined;
    return this.#items[pos].priority;
  }

  /**
   * Lowers the priority of a held key.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority; must not exceed the current one.
   * @returns {void}
   */
  decreaseKey(key, priority) {
    this.#checkKey(key);
    this.#checkPriority(priority);
    const pos = this.#index.get(key);
    if (pos === undefined) throw new ReferenceError(`unknown key: "${key}"`);
    const current = this.#items[pos].priority;
    if (priority > current) throw new RangeError(`priority must not increase for "${key}"`);
    this.#items[pos].priority = priority;
    this.#siftUp(pos);
  }

  /**
   * Sets the priority of a held key in either direction.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority.
